{"name": "enable_rls_on_all_tables", "query": "
-- ============================================================
-- STEP 2: Enable Row Level Security on all five tables
-- ============================================================

ALTER TABLE public.users              ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.channels           ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.posts              ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.comments           ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.channel_moderators ENABLE ROW LEVEL SECURITY;

-- Confirm RLS is now enabled
SELECT
  schemaname,
  tablename,
  rowsecurity AS rls_enabled
FROM pg_tables
WHERE schemaname = 'public'
  AND tablename IN (
    'users', 'channels', 'posts', 'comments', 'channel_moderators'
  )
ORDER BY tablename;
"}

{"query": "
-- ============================================================
-- SCENARIO TEST 1: Content Ownership
-- Alice (11111111) owns the "general" channel.
-- Bob   (22222222) is a moderator of "general".
-- Charlie (33333333) posted "Hello everyone" in "general".
-- Test: Charlie can edit own post; Eve (55555555) cannot.
-- ============================================================

-- Test 1a: is_channel_owner works correctly
SELECT
  'TEST 1a: is_channel_owner' AS test,
  public.is_channel_owner(
    'aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa'::uuid,  -- general channel
    '11111111-1111-1111-1111-111111111111'::uuid   -- alice (owner)
  ) AS alice_is_owner,
  public.is_channel_owner(
    'aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa'::uuid,  -- general channel
    '55555555-5555-5555-5555-555555555555'::uuid   -- eve (not owner)
  ) AS eve_is_owner;
"}

{"query": "
-- Test 1b: is_channel_moderator works correctly
SELECT
  'TEST 1b: is_channel_moderator' AS test,
  public.is_channel_moderator(
    'aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa'::uuid,  -- general channel
    '22222222-2222-2222-2222-222222222222'::uuid   -- bob (moderator of general)
  ) AS bob_is_mod_of_general,
  public.is_channel_moderator(
    'bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb'::uuid,  -- tech-talk channel
    '44444444-4444-4444-4444-444444444444'::uuid   -- diana (moderator of tech-talk)
  ) AS diana_is_mod_of_tech,
  public.is_channel_moderator(
    'aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa'::uuid,  -- general channel
    '55555555-5555-5555-5555-555555555555'::uuid   -- eve (not a moderator)
  ) AS eve_is_mod_of_general;
"}

{"query": "
-- Test 1c: can_moderate_channel – owner + moderator both qualify
SELECT
  'TEST 1c: can_moderate_channel' AS test,
  public.can_moderate_channel(
    'aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa'::uuid,
    '11111111-1111-1111-1111-111111111111'::uuid  -- alice = owner
  ) AS alice_can_moderate,
  public.can_moderate_channel(
    'aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa'::uuid,
    '22222222-2222-2222-2222-222222222222'::uuid  -- bob = moderator
  ) AS bob_can_moderate,
  public.can_moderate_channel(
    'aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa'::uuid,
    '55555555-5555-5555-5555-555555555555'::uuid  -- eve = neither
  ) AS eve_can_moderate;
"}

{"query": "
-- Test 2g: channel_moderators INSERT/DELETE policy
-- Only Alice (owner of "general") can add/remove moderators from "general"
-- Bob (moderator) can remove himself but not others
-- Eve (nobody) cannot add or remove moderators

BEGIN;
  SET LOCAL "app.current_user_id" = '55555555-5555-5555-5555-555555555555'; -- Eve

  SELECT
    'TEST 2g: channel_moderators policies (as Eve/nobody)' AS test,
    cm.channel_id,
    cm.user_id,
    ch.name AS channel,
    -- INSERT policy: must be owner
    public.is_channel_owner(cm.channel_id, public.current_user_id()) AS eve_can_add_mods,
    -- DELETE policy: owner OR self
    (
      public.is_channel_owner(cm.channel_id, public.current_user_id())
      OR cm.user_id = public.current_user_id()
    ) AS eve_can_remove_this_mod
  FROM public.channel_moderators cm
  JOIN public.channels ch ON ch.id = cm.channel_id;
ROLLBACK;
"}

{"query": "
-- Test 2h: Moderator self-removal – Bob (moderator of general) can remove himself
BEGIN;
  SET LOCAL "app.current_user_id" = '22222222-2222-2222-2222-222222222222'; -- Bob

  SELECT
    'TEST 2h: Moderator self-removal (Bob)' AS test,
    cm.channel_id,
    cm.user_id,
    ch.name AS channel,
    public.is_channel_owner(cm.channel_id, public.current_user_id()) AS bob_is_owner,
    (cm.user_id = public.current_user_id())                          AS is_self,
    (
      public.is_channel_owner(cm.channel_id, public.current_user_id())
      OR cm.user_id = public.current_user_id()
    ) AS bob_can_remove_this_mod
  FROM public.channel_moderators cm
  JOIN public.channels ch ON ch.id = cm.channel_id;
ROLLBACK;
"}
